+import { existsSync, readFileSync, renameSync, unlinkSync, writeFileSync } from "node:fs";
+import { basename, dirname, join } from "node:path";
+
+type Status = "open" | "done";
+
+export interface Task {
+  id: number;
+  title: string;
+  tags: string[];
+  status: Status;
+  createdAt: string;
+  due?: string;
+  completedAt?: string;
+}
+
+interface Database {
+  nextId: number;
+  tasks: Task[];
+}
+
+class UsageError extends Error {}
+
+function isDate(value: string): boolean {
+  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
+  const [year, month, day] = value.split("-").map(Number);
+  const date = new Date(Date.UTC(year, month - 1, day));
+  return date.getUTCFullYear() === year && date.getUTCMonth() === month - 1 && date.getUTCDate() === day;
+}
+
+function today(): string {
+  const date = new Date();
+  return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`;
+}
+
+function databasePath(env: Record<string, string | undefined> = process.env): string {
+  return env.TASKBOARD_FILE || join(process.cwd(), ".taskboard.json");
+}
+
+function validTask(value: unknown): value is Task {
+  if (typeof value !== "object" || value === null) return false;
+  const task = value as Partial<Task>;
+  return Number.isSafeInteger(task.id) && task.id! > 0 &&
+    typeof task.title === "string" && Array.isArray(task.tags) && task.tags.every((tag) => typeof tag === "string") &&
+    (task.status === "open" || task.status === "done") && typeof task.createdAt === "string" &&
+    (task.due === undefined || (typeof task.due === "string" && isDate(task.due))) &&
+    (task.completedAt === undefined || typeof task.completedAt === "string");
+}
+
+function loadDatabase(path: string): Database {
+  if (!existsSync(path)) return { nextId: 1, tasks: [] };
+  let value: unknown;
+  try {
+    value = JSON.parse(readFileSync(path, "utf8"));
+  } catch {
+    throw new UsageError(`Malformed database: ${path}`);
+  }
+  if (typeof value !== "object" || value === null) throw new UsageError(`Malformed database: ${path}`);
+  const database = value as Partial<Database>;
+  if (!Number.isSafeInteger(database.nextId) || database.nextId! < 1 || !Array.isArray(database.tasks) || !database.tasks.every(validTask)) {
+    throw new UsageError(`Malformed database: ${path}`);
+  }
+  const ids = new Set<number>();
+  if (database.tasks.some((task) => ids.has(task.id) || (ids.add(task.id), false)) || database.tasks.some((task) => task.id >= database.nextId!)) {
+    throw new UsageError(`Malformed database: ${path}`);
+  }
+  return database as Database;
+}
+
+function saveDatabase(path: string, database: Database): void {
+  const temporary = join(dirname(path), `.${basename(path)}.${process.pid}.${crypto.randomUUID()}.tmp`);
+  try {
+    writeFileSync(temporary, JSON.stringify(database, null, 2) + "\n", "utf8");
+    renameSync(temporary, path);
+  } catch (error) {
+    if (existsSync(temporary)) unlinkSync(temporary);
+    throw error;
+  }
+}
+
+function parseFlags(args: string[], allowed: string[]): Record<string, string> {
+  const flags: Record<string, string> = {};
+  for (let index = 0; index < args.length; index += 2) {
+    const flag = args[index];
+    const value = args[index + 1];
+    if (!flag?.startsWith("--") || !allowed.includes(flag) || value === undefined || value.startsWith("--") || flags[flag] !== undefined) {
+      throw new UsageError("Invalid command arguments");
+    }
+    flags[flag] = value;
+  }
+  return flags;
+}
+
+function parseId(value: string | undefined): number {
+  if (!value || !/^\d+$/.test(value)) throw new UsageError("Task ID must be a positive integer");
+  const id = Number(value);
+  if (!Number.isSafeInteger(id) || id < 1) throw new UsageError("Task ID must be a positive integer");
+  return id;
+}
+
+function normalizedTags(value: string | undefined): string[] {
+  if (!value) return [];
+  return [...new Set(value.split(",").map((tag) => tag.trim().toLowerCase()).filter(Boolean))];
+}
+
+export function run(args: string[], path = databasePath()): unknown {
+  const [command, ...rest] = args;
+  if (!command) throw new UsageError("Missing command");
+  const database = loadDatabase(path);
+
+  if (command === "add") {
+    const flags = parseFlags(rest, ["--title", "--tags", "--due"]);
+    const title = flags["--title"]?.trim();
+    if (!title) throw new UsageError("Title cannot be empty");
+    if (flags["--due"] && !isDate(flags["--due"])) throw new UsageError("Due date must be YYYY-MM-DD");
+    const task: Task = { id: database.nextId++, title, tags: normalizedTags(flags["--tags"]), status: "open", createdAt: new Date().toISOString() };
+    if (flags["--due"]) task.due = flags["--due"];
+    database.tasks.push(task);
+    saveDatabase(path, database);
+    return task;
+  }
+
+  if (command === "list") {
+    const flags = parseFlags(rest, ["--status", "--tag", "--overdue"]);
+    if (flags["--status"] && flags["--status"] !== "open" && flags["--status"] !== "done") throw new UsageError("Status must be open or done");
+    if (flags["--overdue"] && !isDate(flags["--overdue"])) throw new UsageError("Overdue date must be YYYY-MM-DD");
+    const tag = flags["--tag"]?.trim().toLowerCase();
+    return database.tasks.filter((task) =>
+      (!flags["--status"] || task.status === flags["--status"]) &&
+      (!tag || task.tags.includes(tag)) &&
+      (!flags["--overdue"] || (task.status === "open" && task.due !== undefined && task.due < flags["--overdue"]))
+    ).sort((a, b) => a.id - b.id);
+  }
+
+  if (command === "done" || command === "delete") {
+    if (rest.length !== 1) throw new UsageError("Expected one task ID");
+    const id = parseId(rest[0]);
+    const index = database.tasks.findIndex((task) => task.id === id);
+    if (index === -1) throw new UsageError(`Task ${id} does not exist`);
+    if (command === "delete") {
+      database.tasks.splice(index, 1);
+      saveDatabase(path, database);
+      return { deleted: id };
+    }
+    const task = database.tasks[index];
+    if (task.status === "open") {
+      task.status = "done";
+      task.completedAt = new Date().toISOString();
+      saveDatabase(path, database);
+    }
+    return task;
+  }
+
+  if (command === "stats") {
+    if (rest.length) throw new UsageError("Stats takes no arguments");
+    const open = database.tasks.filter((task) => task.status === "open");
+    return { total: database.tasks.length, open: open.length, done: database.tasks.length - open.length, overdue: open.filter((task) => task.due !== undefined && task.due < today()).length };
+  }
+
+  throw new UsageError(`Unknown command: ${command}`);
+}
+
+if (import.meta.main) {
+  try {
+    process.stdout.write(`${JSON.stringify(run(Bun.argv.slice(2)))}\n`);
+  } catch (error) {
+    const message = error instanceof Error ? error.message : "Unexpected error";
+    process.stdout.write(`${JSON.stringify({ error: message })}\n`);
+    process.stderr.write(`${message}\n`);
+    process.exitCode = 1;
+  }
+}
