+import { afterEach, describe, expect, test } from "bun:test";
+import { existsSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
+import { tmpdir } from "node:os";
+import { join } from "node:path";
+
+const directories: string[] = [];
+function board(): string {
+  const directory = mkdtempSync(join(tmpdir(), "taskboard-"));
+  directories.push(directory);
+  return join(directory, "board.json");
+}
+function command(path: string, ...args: string[]) {
+  return Bun.spawnSync(["bun", "run", "src/cli.ts", ...args], { cwd: import.meta.dir + "/..", env: { ...process.env, TASKBOARD_FILE: path }, stdout: "pipe", stderr: "pipe" });
+}
+function output(result: ReturnType<typeof command>) { return JSON.parse(new TextDecoder().decode(result.stdout)); }
+afterEach(() => { for (const directory of directories.splice(0)) rmSync(directory, { recursive: true, force: true }); });
+
+describe("taskboard CLI", () => {
+  test("persists, filters, completes, and deletes tasks", () => {
+    const path = board();
+    const first = output(command(path, "add", "--title", " First task ", "--tags", "Work,urgent,work", "--due", "2026-01-01"));
+    const second = output(command(path, "add", "--title", "Second task", "--tags", "home"));
+    expect(first).toMatchObject({ id: 1, title: "First task", tags: ["work", "urgent"], status: "open", due: "2026-01-01" });
+    expect(second.id).toBe(2);
+    expect(output(command(path, "list", "--tag", "WORK"))).toHaveLength(1);
+    const done = output(command(path, "done", "1"));
+    expect(done.status).toBe("done");
+    expect(output(command(path, "done", "1")).completedAt).toBe(done.completedAt);
+    expect(output(command(path, "list", "--overdue", "2026-02-01"))).toEqual([]);
+    expect(output(command(path, "delete", "2"))).toEqual({ deleted: 2 });
+    expect(output(command(path, "stats"))).toMatchObject({ total: 1, open: 0, done: 1, overdue: 0 });
+  });
+
+  test("rejects invalid input without replacing existing data", () => {
+    const path = board();
+    output(command(path, "add", "--title", "Safe task"));
+    const before = readFileSync(path, "utf8");
+    const result = command(path, "add", "--title", "", "--due", "2026-02-30");
+    expect(result.exitCode).not.toBe(0);
+    expect(output(result).error).toBeTruthy();
+    expect(readFileSync(path, "utf8")).toBe(before);
+  });
+
+  test("rejects malformed databases", () => {
+    const path = board();
+    writeFileSync(path, "not json");
+    const result = command(path, "list");
+    expect(result.exitCode).not.toBe(0);
+    expect(output(result).error).toContain("Malformed database");
+    expect(readFileSync(path, "utf8")).toBe("not json");
+  });
+
+  test("writes the database atomically", () => {
+    const path = board();
+    output(command(path, "add", "--title", "Atomic"));
+    expect(existsSync(path)).toBe(true);
+    expect(JSON.parse(readFileSync(path, "utf8")).tasks).toHaveLength(1);
+  });
+});
